import{_ as i,o as a,c as t,ae as l}from"./chunks/framework.RRduUuAx.js";const m=JSON.parse('{"title":"Policy Evaluation Engine and Deny-by-Default","description":"","frontmatter":{"work_package_id":"WP02","title":"Policy Evaluation Engine and Deny-by-Default","lane":"done","dependencies":["WP01"],"base_branch":"023-command-policy-engine-and-approval-workflows-WP01","base_commit":"ea3eecd927fa6313ae0974c5e175c17767819a74","created_at":"2026-03-01T13:35:28.402260+00:00","subtasks":["T006","T007","T008","T009","T010"],"phase":"Phase 1 - Policy Foundation","assignee":"","agent":"claude-haiku","shell_pid":"80143","review_status":"approved","reviewed_by":"Koosha Paridehpour","history":[{"timestamp":"2026-02-27T00:00:00Z","lane":"planned","agent":"system","shell_pid":"","action":"Prompt generated via /spec-kitty.tasks"}]},"headers":[],"relativePath":"specs/023-command-policy-engine-and-approval-workflows/tasks/WP02-policy-evaluation-engine.md","filePath":"specs/023-command-policy-engine-and-approval-workflows/tasks/WP02-policy-evaluation-engine.md"}'),o={name:"specs/023-command-policy-engine-and-approval-workflows/tasks/WP02-policy-evaluation-engine.md"};function n(s,e,r,c,d,u){return a(),t("div",null,[...e[0]||(e[0]=[l('<h1 id="work-package-prompt-wp02-policy-evaluation-engine-and-deny-by-default" tabindex="-1">Work Package Prompt: WP02 - Policy Evaluation Engine and Deny-by-Default <a class="header-anchor" href="#work-package-prompt-wp02-policy-evaluation-engine-and-deny-by-default" aria-label="Permalink to &quot;Work Package Prompt: WP02 - Policy Evaluation Engine and Deny-by-Default&quot;">​</a></h1><h2 id="objectives-success-criteria" tabindex="-1">Objectives &amp; Success Criteria <a class="header-anchor" href="#objectives-success-criteria" aria-label="Permalink to &quot;Objectives &amp; Success Criteria&quot;">​</a></h2><ul><li>Implement the policy evaluation engine as a central checkpoint for all agent-mediated commands.</li><li>Integrate evaluation into both lane execution and terminal command dispatch.</li><li>Record every evaluation result to the audit sink.</li><li>Verify deny-by-default with randomized testing.</li></ul><p>Success criteria:</p><ul><li>100% of agent-mediated commands are evaluated against policy before execution.</li><li>Unclassified commands are denied in 100% of 1000 randomized test inputs.</li><li>Evaluation latency &lt; 50ms (p95) for up to 500 rules.</li><li>Audit trail contains a record for every evaluation.</li><li>Operator direct commands bypass approval but still produce audit entries.</li></ul><h2 id="context-constraints" tabindex="-1">Context &amp; Constraints <a class="header-anchor" href="#context-constraints" aria-label="Permalink to &quot;Context &amp; Constraints&quot;">​</a></h2><ul><li>Constitution: <code>docs/reference/constitution.md</code></li><li>Plan: <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/kitty-specs/023-command-policy-engine-and-approval-workflows/plan.md</code></li><li>Spec: <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/kitty-specs/023-command-policy-engine-and-approval-workflows/spec.md</code></li><li>WP01 output: PolicyRule, PolicyRuleSet, PolicyStorage.</li></ul><p>Constraints:</p><ul><li>Evaluation must not block the execution hot path for safe commands (&lt; 50ms).</li><li>Deny-by-default is mandatory.</li><li>Operator commands bypass approval but audit-log.</li><li>Keep files under repository limits (target &lt;=350 lines, hard &lt;=500).</li></ul><p>Implementation command:</p><ul><li><code>spec-kitty implement WP02</code></li></ul><h2 id="subtasks-detailed-guidance" tabindex="-1">Subtasks &amp; Detailed Guidance <a class="header-anchor" href="#subtasks-detailed-guidance" aria-label="Permalink to &quot;Subtasks &amp; Detailed Guidance&quot;">​</a></h2><h3 id="subtask-t006-implement-policyevaluationengine" tabindex="-1">Subtask T006 - Implement PolicyEvaluationEngine <a class="header-anchor" href="#subtask-t006-implement-policyevaluationengine" aria-label="Permalink to &quot;Subtask T006 - Implement PolicyEvaluationEngine&quot;">​</a></h3><ul><li>Purpose: Centralize all policy evaluation logic into a single engine that consumes command context and returns a classification decision.</li><li>Steps: <ol><li>Create <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/policy/engine.ts</code>.</li><li>Implement <code>PolicyEvaluationEngine</code> class that: <ul><li>Accepts <code>PolicyStorage</code> as a dependency (injected).</li><li>Exposes <code>evaluate(command: string, context: CommandContext): PolicyEvaluationResult</code>.</li><li>Loads the appropriate workspace rule set from storage.</li><li>Delegates to <code>PolicyRuleSet.evaluate()</code> for pattern matching and classification.</li><li>Records evaluation timing (start/end timestamps).</li><li>Returns <code>PolicyEvaluationResult</code> with: classification, matched rules, evaluation duration, deny-by-default flag.</li></ul></li><li>Handle edge cases: <ul><li>If storage is unavailable, deny the command (fail-closed).</li><li>If the workspace has no rules, deny by default.</li><li>If the command context indicates direct operator input (<code>isDirect: true</code>), return <code>&quot;safe&quot;</code> classification but flag <code>bypassedApproval: true</code> for audit.</li></ul></li><li>Export the engine for integration by lane execution and terminal dispatch modules.</li><li>Add logging for denied commands at warn level, approved at debug level.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/policy/engine.ts</code></li></ul></li><li>Acceptance: <ul><li>Engine correctly evaluates commands using workspace-scoped rules.</li><li>Fail-closed on storage unavailability.</li><li>Operator bypass flagged for audit.</li><li>Evaluation timing recorded.</li></ul></li><li>Parallel: No.</li></ul><h3 id="subtask-t007-integrate-policy-evaluation-into-lane-execution-pipeline" tabindex="-1">Subtask T007 - Integrate policy evaluation into lane execution pipeline <a class="header-anchor" href="#subtask-t007-integrate-policy-evaluation-into-lane-execution-pipeline" aria-label="Permalink to &quot;Subtask T007 - Integrate policy evaluation into lane execution pipeline&quot;">​</a></h3><ul><li>Purpose: Ensure every command executed via lane-based agent workflows is policy-checked before execution.</li><li>Steps: <ol><li>Identify the lane execution entry point in <code>apps/runtime/src/integrations/exec.ts</code> or the appropriate lane execution module.</li><li>Add a pre-execution hook that calls <code>PolicyEvaluationEngine.evaluate()</code> with the command and lane context.</li><li>On <code>&quot;safe&quot;</code> classification: proceed with execution immediately.</li><li>On <code>&quot;needs-approval&quot;</code> classification: create an ApprovalRequest (WP03) and suspend the lane execution until resolved.</li><li>On <code>&quot;blocked&quot;</code> classification: reject the command immediately with a structured error message including the matching rule and reason.</li><li>Ensure the hook does not add measurable latency for safe commands (&lt; 50ms overhead).</li><li>Publish a <code>policy.evaluation.completed</code> event on the bus with the evaluation result.</li><li>Test: verify a safe command through lane execution has minimal added latency.</li><li>Test: verify a blocked command through lane execution is rejected with clear diagnostics.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/integrations/exec.ts</code> (or equivalent)</li><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/policy/engine.ts</code> (integration)</li></ul></li><li>Acceptance: <ul><li>All lane-executed commands pass through policy evaluation.</li><li>Safe commands execute without perceptible delay.</li><li>Blocked commands produce clear rejection messages.</li></ul></li><li>Parallel: No.</li></ul><h3 id="subtask-t008-integrate-policy-evaluation-into-terminal-command-dispatch" tabindex="-1">Subtask T008 - Integrate policy evaluation into terminal command dispatch <a class="header-anchor" href="#subtask-t008-integrate-policy-evaluation-into-terminal-command-dispatch" aria-label="Permalink to &quot;Subtask T008 - Integrate policy evaluation into terminal command dispatch&quot;">​</a></h3><ul><li>Purpose: Ensure terminal commands issued by agents (not direct operator input) are policy-checked.</li><li>Steps: <ol><li>Identify the terminal command dispatch path in the runtime where agent-initiated terminal commands are processed.</li><li>Add a pre-dispatch hook that calls <code>PolicyEvaluationEngine.evaluate()</code> with the command and terminal/session context.</li><li>Handle the three classifications as in T007 (safe: proceed, needs-approval: queue, blocked: reject).</li><li>Distinguish between agent-initiated and operator-initiated commands using the <code>isDirect</code> flag in context.</li><li>Operator-initiated commands bypass approval but still produce audit entries.</li><li>Ensure the dispatch hook is on the critical path for agent commands but does not interfere with operator commands.</li><li>Test: verify agent terminal command is policy-evaluated.</li><li>Test: verify direct operator terminal command bypasses approval but is audit-logged.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/sessions/</code> (terminal dispatch module)</li><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/policy/engine.ts</code> (integration)</li></ul></li><li>Acceptance: <ul><li>Agent terminal commands are policy-evaluated.</li><li>Operator commands bypass approval.</li><li>Both produce audit entries.</li></ul></li><li>Parallel: No.</li></ul><h3 id="subtask-t009-wire-evaluation-results-to-audit-sink" tabindex="-1">Subtask T009 - Wire evaluation results to audit sink <a class="header-anchor" href="#subtask-t009-wire-evaluation-results-to-audit-sink" aria-label="Permalink to &quot;Subtask T009 - Wire evaluation results to audit sink&quot;">​</a></h3><ul><li>Purpose: Ensure every policy evaluation is recorded in the audit trail for forensic analysis.</li><li>Steps: <ol><li>After each evaluation in <code>PolicyEvaluationEngine</code>, create a <code>PolicyEvaluationAuditEvent</code> with: <ul><li><code>eventType</code>: &quot;policy.evaluation&quot;</li><li><code>actor</code>: agent ID or operator ID</li><li><code>command</code>: the evaluated command text</li><li><code>classification</code>: the result classification</li><li><code>matchedRules</code>: array of matched rule IDs</li><li><code>denyByDefault</code>: boolean flag</li><li><code>evaluationDurationMs</code>: number</li><li><code>workspaceId</code>, <code>laneId</code>, <code>sessionId</code> from context</li><li><code>correlationId</code> from the originating command</li></ul></li><li>Write the event to the audit sink (spec 024) asynchronously (must not block evaluation).</li><li>Ensure the audit write never fails silently: if the sink is unavailable, buffer the event and retry.</li><li>Verify audit completeness: every evaluation produces exactly one audit event.</li><li>Test: verify audit events are written for safe, blocked, and needs-approval evaluations.</li><li>Test: verify audit events are written for operator-bypassed commands.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/policy/engine.ts</code> (audit integration)</li><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/audit/</code> (event type registration)</li></ul></li><li>Acceptance: <ul><li>Every evaluation produces an audit event.</li><li>Audit writes are async and do not block evaluation.</li><li>Buffering on sink unavailability.</li></ul></li><li>Parallel: No.</li></ul><h3 id="subtask-t010-deny-by-default-verification-and-performance-benchmarks" tabindex="-1">Subtask T010 - Deny-by-default verification and performance benchmarks <a class="header-anchor" href="#subtask-t010-deny-by-default-verification-and-performance-benchmarks" aria-label="Permalink to &quot;Subtask T010 - Deny-by-default verification and performance benchmarks&quot;">​</a></h3><ul><li>Purpose: Prove that deny-by-default holds under randomized inputs and that evaluation performance meets the 50ms p95 target.</li><li>Steps: <ol><li>Create <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/tests/unit/policy/deny-by-default.test.ts</code>.</li><li>Generate 1000 randomized command strings (using random words, paths, and special characters).</li><li>Evaluate each against a workspace with known rules (10 safe, 10 needs-approval, 10 blocked).</li><li>Verify that any command not matching a rule is classified as <code>&quot;blocked&quot;</code> with <code>denyByDefault: true</code>.</li><li>Verify zero unclassified commands escape as <code>&quot;safe&quot;</code>.</li><li>Create <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/tests/unit/policy/performance.test.ts</code>.</li><li>Generate a rule set with 500 rules (mix of glob and regex).</li><li>Evaluate 1000 commands and measure p95 latency.</li><li>Assert p95 &lt; 50ms.</li><li>If p95 exceeds target, profile and optimize (pre-compile patterns, reduce iteration).</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/tests/unit/policy/deny-by-default.test.ts</code></li><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/tests/unit/policy/performance.test.ts</code></li></ul></li><li>Acceptance: <ul><li>1000/1000 unmatched commands denied.</li><li>p95 evaluation latency &lt; 50ms with 500 rules.</li><li>Zero false allows.</li></ul></li><li>Parallel: Yes (after T006 engine is functional).</li></ul><h2 id="test-strategy" tabindex="-1">Test Strategy <a class="header-anchor" href="#test-strategy" aria-label="Permalink to &quot;Test Strategy&quot;">​</a></h2><ul><li>Randomized deny-by-default verification (1000 commands).</li><li>Performance benchmarks with 500 rules.</li><li>Integration tests for lane and terminal dispatch hooks.</li><li>Audit completeness verification.</li></ul><h2 id="risks-mitigations" tabindex="-1">Risks &amp; Mitigations <a class="header-anchor" href="#risks-mitigations" aria-label="Permalink to &quot;Risks &amp; Mitigations&quot;">​</a></h2><ul><li>Risk: Evaluation hook adds latency to safe command execution.</li><li>Mitigation: Pre-compile patterns; in-memory cache; benchmark in CI.</li><li>Risk: Audit sink backpressure causes evaluation blocking.</li><li>Mitigation: Async audit writes with bounded buffer.</li></ul><h2 id="review-guidance" tabindex="-1">Review Guidance <a class="header-anchor" href="#review-guidance" aria-label="Permalink to &quot;Review Guidance&quot;">​</a></h2><ul><li>Confirm deny-by-default holds for all unmatched commands.</li><li>Confirm operator commands bypass approval but audit-log.</li><li>Confirm evaluation integrates into both lane and terminal paths.</li><li>Confirm performance meets 50ms p95 target.</li></ul><h2 id="activity-log" tabindex="-1">Activity Log <a class="header-anchor" href="#activity-log" aria-label="Permalink to &quot;Activity Log&quot;">​</a></h2><ul><li>2026-02-27T00:00:00Z – system – lane=planned – Prompt created.</li><li>2026-03-01T13:35:28Z – claude-haiku – shell_pid=80143 – lane=doing – Assigned agent via workflow command</li><li>2026-03-01T13:36:03Z – claude-haiku – shell_pid=80143 – lane=done – Implemented</li></ul>',30)])])}const h=i(o,[["render",n]]);export{m as __pageData,h as default};
